        # Auto-committed to session on handler completion
        return ctx.json({"items": state.items})

from aquilia.auth import authenticated, scopes_required
from aquilia.sessions import session


class OrderController(Controller):
    prefix = "/orders"

    @Get("/")
    @authenticated                          # Enforces authentication (auth module)
    @scopes_required("orders:read")         # Enforces permission (auth module)
    async def list_orders(self, ctx, user):
        orders = await Order.objects.filter(user_id=user.id)
        return ctx.json([o.to_dict() for o in orders])

    @Post("/")
    @session.require(authenticated=True)    # Enforces session & auth
    @scopes_required("orders:write")        # Enforces permission check
    async def create_order(self, ctx, session):
        body = await ctx.request.json()
        order = await Order.create(
            user_id=session.principal.id,
            **body,
        )
        return ctx.json(order.to_dict(), status=201)

from aquilia import Controller, Get, Post
from aquilia.sessions import stateful
from aquilia.sessions.state import UserPreferencesState


class SettingsController(Controller):
    prefix = "/settings"

    @Get("/")
    @stateful
    async def get_prefs(self, ctx, state: UserPreferencesState):
        return ctx.json({
            "theme": state.theme,
            "locale": state.language,
            "timezone": state.timezone,
        })

    @Post("/")
    @stateful
    async def update_prefs(self, ctx, state: UserPreferencesState):
        body = await ctx.request.json()
        if "theme" in body:
            state.theme = body["theme"]
        if "locale" in body:
            state.language = body["locale"]
        return ctx.json({"updated": True})

from aquilia.faults import fault_handler
from aquilia.sessions.faults import (
    SessionFault,
    SessionExpiredFault,
    SessionHijackAttemptFault,
    SessionStoreUnavailableFault,
)

# Catch generic session faults
@fault_handler(SessionFault)
async def handle_session_fault(ctx, fault):
    return ctx.json({
        "error": fault.message,
        "code": fault.code,
        "retryable": fault.retryable,
    }, status=fault.http_status)


# Catch specific fault (graceful redirect)
@fault_handler(SessionExpiredFault)
async def handle_expired(ctx, fault):
    return ctx.redirect("/login?reason=expired")


# Catch security hijacking fault (terminate user sessions)
@fault_handler(SessionHijackAttemptFault)
async def handle_hijack(ctx, fault):
    # Retrieve active session from RequestCtx (fault has no .session property)
    session = ctx.session

    if session and session.principal:
        # Delete user sessions to mitigate attack
        active_sessions = await ctx.store.list_by_principal(session.principal.id)
        for s in active_sessions:
            await ctx.store.delete(s.id)

    return ctx.json({"error": "Access denied"}, status=403)

