    isAlwaysOn: false,
    codeSnippet: '# Registration in default fallback chain\nself.middleware_stack.add(\n    ExceptionMiddleware(debug=self._is_debug()),\n    scope="global",\n    priority=1,\n    name="exception"\n)'
  },
  {
    id: 'fault',
    name: 'Fault Interceptor',
