    codeSnippet: '# Configure via workspace integration\nworkspace.integrate(\n    Integration.proxy_fix(\n        trusted_proxies=["127.0.0.1"]\n    )\n)'
  },
  {
    id: 'httpsredirect',
    name: 'HTTPS Enforcer',
    fullName: 'aquilia.middleware.HTTPSRedirectMiddleware',
    priority: 4,
