@service(scope="request")
class UnitOfWork:
    def __init__(self, db: Database):     # db is app-scoped, shared
        self.db = db
        self.tx = None

    async def async_init(self):
        self.tx = await self.db.begin()

    async def commit(self):
        await self.tx.commit()

