class SignerBackend(ABC):
    @abstractmethod
    def sign(self, message: bytes) -> bytes: ...
    @abstractmethod
    def verify(self, message: bytes, signature: bytes) -> bool: ...
    @property
    @abstractmethod
    def algorithm(self) -> str: ...

