class ProjectRepository:
    async def get(self, key: str) -> dict:
        row = self._rows.get(key.upper())
        if row is None:
            raise NotFoundFault(detail=f"Project {key!r} was not found")
        return row.to_dict()

    async def create(self, data: dict) -> dict:
        key = data["key"].upper()
        if key in self._rows:
