    class Meta:
        fields = {"category": ["exact"], "price": ["gte", "lte"]}

    def filter_category(self, value: str) -> dict:
        """Map 'sale' to special clause"""
        if value == "sale":
            return {"discount__gt": 0}
        return {"category": value}

