        )
        from aquilia.di import Inject

        @Socket("/chat/:namespace")
        class ChatSocket(SocketController):
            def __init__(self, presence=Inject(tag="presence")):
                self.presence = presence

            @OnConnect()
            async def on_connect(self, conn: Connection):
                await conn.send_event("system.welcome", {
                    "msg": f"Welcome {conn.identity.id}"
                })

            @Event("message.send", schema=Schema({
                "room": str,
                "text": str
            }))
            async def handle_message(self, conn: Connection, payload):
                room = payload["room"]
                await self.publish_room(room, "message.receive", {
                    "from": conn.identity.id,
                    "text": payload["text"]
                })

Class aquilia.models.manager.and
Module: aquilia.models.manager

Docstring:
Default manager -- auto-attached as ``objects`` on every Model.

    Override ``get_queryset()`` for custom pre-filtered managers:

        class PublishedManager(Manager):
            def get_queryset(self):
                return super().get_queryset().filter(status="published")

        class Article(Model):
            table = "articles"
            title = CharField(max_length=200)
            status = CharField(max_length=20, default="draft")

            objects = Manager()             # default (all articles)
            published = PublishedManager()  # pre-filtered

        # Usage:
        all_articles = await Article.objects.all()
        pub_articles = await Article.published.filter(author="Alice").all()

    Or use from_queryset() to compose reusable query methods:

        class ArticleQuerySet(QuerySet):
            def published(self):
                return self.get_queryset().filter(status="published")

            def by_author(self, author_id):
                return self.get_queryset().filter(author_id=author_id)

        ArticleManager = Manager.from_queryset(ArticleQuerySet)

Class aquilia.controller.filters.FilterSet
Module: aquilia.controller.filters

Docstring:
Declarative filter specification.

    Parses query parameters from the request and produces a dict of
    ``{field__lookup: coerced_value}`` clauses that can be fed directly
    into ``Model.objects.filter()`` or ``apply_filters_to_list()``.

    Usage::

        class ProductFilter(FilterSet):
            class Meta:
                fields = {
                    "category": ["exact", "in"],
                    "price": ["gte", "lte", "range"],
                    "is_active": ["exact"],
                }

        # In controller -- engine does this automatically:
        fs = ProductFilter(request=request)
        clauses = fs.parse()  # {"category": "electronics", "price__gte": 10}

    Custom filter methods
    ---------------------
    Define ``filter_<field>`` to override default behaviour::

        class ProductFilter(FilterSet):
            class Meta:
                fields = {"category": ["exact"]}

            def filter_category(self, value: str) -> dict:
                # Map "sale" → special clause
                if value == "sale":
                    return {"discount__gt": 0}
                return {"category": value}

